import {expect as baseExpect} from '@playwright/test'
import {randomUUID,randomBytes,createHash} from 'node:crypto'
import {mkdirSync,writeFileSync} from 'node:fs'
import sharp from 'sharp'
import {expectSuccess,expectDatabaseError} from '../../scripts/staging/assertions.mjs'
const expect=baseExpect.configure({timeout:30000})
export async function prepareConcerns(actors,label='SYNTHETIC site concern'){
 const company=randomUUID(),tag=label+' '+company.slice(0,6),rpc=(role,fn,command,p)=>actors[role].client.rpc(fn,{command,p:{companyId:company,requestId:randomUUID(),...p}}).then(expectSuccess)
 await rpc('OWNER','ts_command','create_company',{id:company,name:tag})
 for(const role of ['WORKER','SUPERVISOR']){const token=randomBytes(32).toString('hex');await rpc('OWNER','ts_command','invite',{email:actors[role].email,role:role.toLowerCase(),token});await rpc(role,'ts_command','accept_invitation',{token})}
 const site=await rpc('WORKER','ts_site_command','create',{id:randomUUID(),document:{name:tag,address:'SYNTHETIC loading bay',instructions:''}})
 return {company,tag,siteId:site.id}
}
export async function concernWorkflow({browser,origin,actors,options={},capture=async()=>{},record=()=>{}}){
 const f=await prepareConcerns(actors),{company,siteId}=f,contexts=[];let stage='setup',httpFailure=null
 const rpc=(role,fn,command,p={})=>actors[role].client.rpc(fn,{command,p:{companyId:company,requestId:randomUUID(),...p}}),cmd=(role,n,p)=>rpc(role,'ts_command',n,p).then(expectSuccess)
 const rows=(role,t,k,v)=>actors[role].client.from(t).select('*').eq(k,v).then(expectSuccess)
 async function login(role){const {localOnly,...settings}=options,c=await browser.newContext({viewport:{width:390,height:844},...settings});contexts.push(c);if(localOnly)await c.route('**/*',r=>[origin,actors[role].apiOrigin].includes(new URL(r.request().url()).origin)?r.continue():r.abort());const p=await c.newPage();p.setDefaultTimeout(30000);p.setDefaultNavigationTimeout(90000);await p.goto(origin+'/auth/login');await p.getByLabel('Email',{exact:true}).fill(actors[role].email);await p.getByLabel('Password',{exact:true}).fill(actors[role].password);await p.getByRole('button',{name:'Sign In',exact:true}).click();await p.waitForURL('**/dashboard');return p}
 async function committed(route,postData){const response=await route.fetch(postData?{postData}:{});if(response.status()!==200){let code='unreadable';try{const b=await response.json();if(/^[a-z_]{1,40}$/.test(b.code||''))code=b.code}catch{}httpFailure={status:response.status(),code}}expect(response.status()).toBe(200)}
 const screen=async(p,n)=>{expect(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await capture(p,n)}
 try{
  const worker=await login('WORKER'),supervisor=await login('SUPERVISOR'),outsider=await login('OUTSIDER'),api=origin+'/api/concerns'
  stage='capture';await worker.goto(origin+'/sites/'+siteId);await worker.getByRole('link',{name:'Report a concern',exact:true}).click();await expect(worker.getByRole('button',{name:'Save concern draft',exact:true})).toBeEnabled()
  await worker.getByLabel('What did you observe?',{exact:true}).fill('SYNTHETIC cone beside blocked route');await worker.keyboard.press('Tab');await expect(worker.getByLabel('Where on this site?',{exact:true})).toBeFocused();expect(await worker.getByLabel('Where on this site?',{exact:true}).evaluate(e=>getComputedStyle(e).outlineStyle)).not.toBe('none');await worker.getByLabel('Where on this site?',{exact:true}).fill('SYNTHETIC bay 2');await screen(worker,'capture-unsaved')
  // Actual creation commits; the browser sees a dropped response and safely retries.
  let lost=false;await worker.context().route(api,async r=>{if(r.request().postDataJSON()?.command==='create'&&!lost){lost=true;await committed(r);await r.abort()}else await r.continue()})
  await worker.getByRole('button',{name:'Save concern draft',exact:true}).click();await expect(worker.getByRole('button',{name:'Retry same concern operation',exact:true})).toBeVisible();await expect(worker.getByLabel('What did you observe?',{exact:true})).toHaveValue('SYNTHETIC cone beside blocked route');await worker.getByRole('button',{name:'Retry same concern operation',exact:true}).click();await worker.waitForURL(/\/concerns\/[a-f0-9-]{36}$/);await worker.context().unroute(api)
  const id=new URL(worker.url()).pathname.split('/').at(-1);f.concernId=id;expect(await rows('WORKER','ts_concerns','site_id',siteId)).toHaveLength(1)
  await worker.reload();await expect(worker.getByRole('status').filter({hasText:'Saved concern draft'})).toBeVisible();await expect(worker.getByLabel('Where on this site?',{exact:true})).toHaveValue('SYNTHETIC bay 2')
  stage='photo';const svg='<svg width="320" height="240" xmlns="http://www.w3.org/2000/svg"><rect width="320" height="240" fill="white"/><path d="M160 30 L240 210 H80 Z" fill="orange"/><text x="20" y="230" font-size="20">SYNTHETIC CONCERN</text></svg>',photo=await sharp(Buffer.from(svg)).jpeg().withExif({IFD0:{Artist:'Synthetic untrusted capture'}}).toBuffer(),photoApi=origin+'/api/concerns/'+id+'/evidence'
  // WebKit interception does not reliably expose a file-backed request body to
  // route.fetch. Supply the selected fixture bytes for this injected response-loss
  // request; the subsequent UI retry is an unintercepted browser file upload.
  let photoLost=false;await worker.context().route(photoApi,async r=>{if(r.request().method()==='POST'&&!photoLost){photoLost=true;f.interceptedPhotoBodyBytes=r.request().postDataBuffer()?.length??0;f.selectedPhotoBytes=photo.length;await committed(r,photo);await r.abort()}else await r.continue()})
  await worker.getByLabel('Photo file',{exact:true}).setInputFiles({name:'SYNTHETIC-orange-cone.jpg',mimeType:'image/jpeg',buffer:photo});await worker.getByLabel('Photo caption',{exact:true}).fill('SYNTHETIC orange cone at bay 2');await worker.getByRole('button',{name:'Upload photo',exact:true}).click();await expect(worker.getByRole('button',{name:'Retry selected photo',exact:true})).toBeVisible();await worker.getByRole('button',{name:'Retry selected photo',exact:true}).click();await expect(worker.getByRole('status').filter({hasText:'Photo saved and retained.'})).toBeVisible();await worker.context().unroute(photoApi);await worker.reload();await expect(worker.getByRole('img',{name:'SYNTHETIC orange cone at bay 2',exact:true})).toBeVisible()
  const photos=await rows('WORKER','ts_concern_photos','concern_id',id);expect(photos).toHaveLength(1);const imageUrl=photoApi+'/'+photos[0].id,bytes=await(await worker.context().request.get(imageUrl)).body(),hash=createHash('sha256').update(bytes).digest('hex');expect(hash).toBe(photos[0].sha256);expect((await sharp(bytes).metadata()).exif).toBeUndefined();f.photoHash=hash
  stage='submit';let submissionLost=false;await worker.context().route(api,async r=>{if(r.request().postDataJSON()?.command==='submit'&&!submissionLost){submissionLost=true;await committed(r);await r.abort()}else await r.continue()})
  await worker.getByRole('button',{name:'Submit concern',exact:true}).click();await expect(worker.getByRole('button',{name:'Retry same concern operation',exact:true})).toBeVisible();await worker.getByRole('button',{name:'Retry same concern operation',exact:true}).click();await worker.getByRole('link',{name:'View concern and follow-up',exact:true}).click();await worker.context().unroute(api);await expect(worker.getByRole('heading',{name:'Original observation',exact:true})).toBeVisible();await screen(worker,'submitted-concern')
  const original=(await rows('WORKER','ts_concerns','id',id))[0],actions=await rows('WORKER','ts_actions','concern_id',id);expect(actions).toHaveLength(1);expect(original.submitted_at).toBeTruthy();const actionId=actions[0].id;f.actionId=actionId
  stage='correction-note';await worker.getByText('Add a correction note',{exact:true}).click();await worker.getByLabel('Correction note',{exact:true}).fill('   ');await worker.getByRole('button',{name:'Save correction note',exact:true}).click();await expect(worker.getByRole('alert')).toContainText('Enter a correction note before saving.');await expect(worker.getByLabel('Correction note',{exact:true})).toBeEditable();await worker.getByLabel('Correction note',{exact:true}).fill('SYNTHETIC clarification: route beside bay 2');await worker.getByRole('button',{name:'Save correction note',exact:true}).click();await expect(worker.getByRole('status').filter({hasText:'Correction note saved.'})).toBeVisible();await worker.reload();await expect(worker.getByText('SYNTHETIC clarification: route beside bay 2',{exact:true})).toBeVisible()
  stage='access-denial';await outsider.goto(origin+'/concerns/'+id);await expect(outsider.getByRole('heading',{name:'Page or report not found',exact:true})).toBeVisible();expect((await outsider.context().request.get(imageUrl)).status()).toBe(404)
  for(const t of ['ts_concerns','ts_concern_photos','ts_actions','ts_concern_notes'])expect(await rows('OUTSIDER',t,'company_id',company)).toHaveLength(0)
  const token=randomBytes(32).toString('hex');await cmd('OWNER','invite',{email:actors.OUTSIDER.email,role:'worker',token});await cmd('OUTSIDER','accept_invitation',{token});await outsider.goto(origin+'/concerns/'+id);await expect(outsider.getByRole('heading',{name:'Page or report not found',exact:true})).toBeVisible();expect((await outsider.context().request.get(imageUrl)).status()).toBe(404);expect(await rows('OUTSIDER','ts_actions','concern_id',id)).toHaveLength(0);expect((await rows('OUTSIDER','ts_events','concern_id',id))).toHaveLength(0)
  stage='follow-up';await worker.goto(origin+'/my-work?company='+company);await expect(worker.getByRole('heading',{name:'Concerns I reported',exact:true})).toBeVisible();await worker.locator('a[href^="/concerns/'+id+'?"]').click();await worker.getByRole('link',{name:'Open follow-up action',exact:true}).click();const card=worker.locator('#action-'+actionId);await card.getByLabel('Progress or resolution notes',{exact:true}).fill('SYNTHETIC worker progress');await card.getByRole('button',{name:'Save progress',exact:true}).click();await expect(card.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible();await worker.reload();await expect(card.getByLabel('Progress or resolution notes',{exact:true})).toHaveValue('SYNTHETIC worker progress')
  let a=(await rows('OWNER','ts_actions','id',actionId))[0];const update={id:actionId,revision:a.revision,controls:a.controls,resolution:a.resolution,targetDate:'',state:'open',responsibleId:actors.SUPERVISOR.id};expectDatabaseError(await rpc('WORKER','ts_command','update_action',update),'TS_denied')
  const actionUrl='/actions?'+new URLSearchParams({company,site:siteId,mine:'0',status:'all',focus:actionId});await supervisor.goto(origin+actionUrl);const sup=supervisor.locator('#action-'+actionId);await sup.getByText('Assignment, due date and immediate controls',{exact:true}).click();await sup.getByLabel('Responsible member',{exact:true}).selectOption(actors.OUTSIDER.id);await sup.getByRole('button',{name:'Save progress',exact:true}).click();await expect(sup.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible();await supervisor.reload();await sup.getByText('Action history',{exact:true}).click();await expect(sup.getByText('Assignment:',{exact:false})).toBeVisible()
  await outsider.goto(origin+'/concerns/'+id);await expect(outsider.getByRole('heading',{name:'Original observation',exact:true})).toBeVisible();expect((await outsider.context().request.get(imageUrl)).status()).toBe(200)
  await outsider.getByRole('link',{name:'Open follow-up action',exact:true}).click();const assigned=outsider.locator('#action-'+actionId);await assigned.getByLabel('Progress or resolution notes',{exact:true}).fill('SYNTHETIC ready for verification');await assigned.getByLabel('Status after saving',{exact:true}).selectOption('awaiting_verification');await assigned.getByRole('button',{name:'Request verification',exact:true}).click();await expect(assigned.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible()
  a=(await rows('OWNER','ts_actions','id',actionId))[0];expectDatabaseError(await rpc('OUTSIDER','ts_command','update_action',{...update,revision:a.revision,state:'closed',responsibleId:actors.OUTSIDER.id}),'TS_denied')
  await supervisor.reload();await sup.getByLabel('Status after saving',{exact:true}).selectOption('closed');await sup.getByRole('button',{name:'Verify and close',exact:true}).click();await expect(sup.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible();await supervisor.reload();await expect(sup).toContainText('Verified by');await sup.getByLabel('Status after saving',{exact:true}).selectOption('open');await sup.getByRole('button',{name:'Reopen action',exact:true}).click();await expect(sup.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible();await supervisor.reload();expect((await rows('OWNER','ts_actions','id',actionId))[0].state).toBe('open')
  stage='revoked-and-integrity';await cmd('OWNER','member',{userId:actors.OUTSIDER.id,role:'remove'});await outsider.goto(origin+'/concerns/'+id);await expect(outsider.getByRole('heading',{name:'Page or report not found',exact:true})).toBeVisible();expect((await outsider.context().request.get(imageUrl)).status()).toBe(404)
  expect(await rows('OUTSIDER','ts_actions','concern_id',id)).toHaveLength(0);expectDatabaseError(await rpc('OUTSIDER','ts_command','update_action',update),'TS_denied');expect((await rows('WORKER','ts_concerns','id',id))[0]).toEqual(original);expect(await rows('WORKER','ts_concern_photos','concern_id',id)).toEqual(photos);expect(createHash('sha256').update(await(await worker.context().request.get(imageUrl)).body()).digest('hex')).toBe(hash)
  expect((await worker.context().request.delete(imageUrl,{headers:{origin,'X-Expected-Actor':actors.WORKER.id}})).status()).toBe(403)
  await worker.goto(origin+'/my-work?company='+company);await expect(worker.locator('a[href^="/concerns/'+id+'?"]')).toBeVisible();await screen(worker,'reported-work')
  record('Concern capture/photo/reload, committed response-loss retries, scoped ownership/progress/verification/reopening, correction notes, private access denial and unchanged original bytes PASS',f)
 }catch(e){mkdirSync('test-results',{recursive:true});writeFileSync('test-results/concern-stage.json',JSON.stringify({stage,name:e.name,httpFailure}));throw e}finally{for(const c of contexts)await c.close()}
}
